// Builds the governance report from the three answers of the public API.
const settings = $('Settings').first().json;
const instanceUrl = settings.baseUrl.replace(/\/api\/v1\/?$/, '');

// Each "Get" node gives one item for each page. Join the pages.
const all = (nodeName) => $(nodeName).all().flatMap((item) => item.json.data ?? []);
const workflows = all('Get workflows');
const apiKeys = all('Get API keys');
const users = all('Get users');

const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
// True when the date is missing or older than the number of days.
const olderThan = (date, days) => !date || now - new Date(date).getTime() > days * DAY;
const day = (date) => (date ? String(date).slice(0, 10) : 'never');

const place = (w) =>
	w.homeProject?.type === 'personal'
		? `personal space of ${w.owner?.email ?? 'an unknown user'}`
		: `project ${w.homeProject?.name ?? 'unknown'}`;
const workflowEntry = (w, detail) => ({
	text: `${w.name} (${place(w)}${detail ? `, ${detail}` : ''})`,
	link: `${instanceUrl}/workflow/${w.id}`,
});
const keyEntry = (k, detail) => ({
	text: `${k.label} of ${k.user.email ?? k.user.id} (${detail})`,
});
const userEntry = (u, detail) => ({
	text: `${u.email} (${detail})`,
});

const failed = (w) => w.recentExecutions.filter((e) => e.status === 'error' || e.status === 'crashed');

const sections = [
	{
		title: 'Published workflows in personal spaces',
		entries: workflows
			.filter((w) => w.status === 'published' && w.homeProject?.type === 'personal')
			.map((w) => workflowEntry(w)),
	},
	{
		title: 'Published workflows with failed executions',
		entries: workflows
			.filter((w) => w.status === 'published' && failed(w).length > 0)
			.map((w) =>
				workflowEntry(w, `${failed(w).length} of the last ${w.recentExecutions.length} executions failed`),
			),
	},
	{
		title: 'Published workflows with unpublished changes',
		entries: workflows.filter((w) => w.hasUnpublishedChanges).map((w) => workflowEntry(w)),
	},
	{
		title: 'Expired API keys',
		entries: apiKeys.filter((k) => k.expired).map((k) => keyEntry(k, `expired ${day(k.expiresAt)}`)),
	},
	{
		title: `API keys not used for ${settings.unusedKeyDays} days`,
		entries: apiKeys
			.filter(
				(k) =>
					!k.expired &&
					olderThan(k.lastUsedAt, settings.unusedKeyDays) &&
					olderThan(k.createdAt, settings.unusedKeyDays),
			)
			.map((k) => keyEntry(k, `last use ${day(k.lastUsedAt)}`)),
	},
	{
		title: `Users not active for ${settings.inactiveDays} days`,
		entries: users
			.filter(
				(u) =>
					!u.isPending &&
					olderThan(u.lastActiveAt, settings.inactiveDays) &&
					olderThan(u.createdAt, settings.inactiveDays),
			)
			.map((u) => userEntry(u, `last active ${day(u.lastActiveAt)}`)),
	},
	{
		title: `Invitations open for more than ${settings.pendingInviteDays} days`,
		entries: users
			.filter((u) => u.isPending && olderThan(u.createdAt, settings.pendingInviteDays))
			.map((u) => userEntry(u, `invited ${day(u.createdAt)}`)),
	},
];

const summary = {
	workflows: workflows.length,
	publishedWorkflows: workflows.filter((w) => w.status === 'published').length,
	workflowsInPersonalSpaces: workflows.filter((w) => w.homeProject?.type === 'personal').length,
	apiKeys: apiKeys.length,
	users: users.filter((u) => !u.isPending).length,
	pendingInvitations: users.filter((u) => u.isPending).length,
};
const findings = sections.reduce((total, section) => total + section.entries.length, 0);
const count = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const subject = `n8n governance report ${new Date().toISOString().slice(0, 10)}: ${count(findings, 'finding')}`;

// Show at most this many entries in each section of the email.
const MAX_ENTRIES = 50;
const escape = (value) =>
	String(value).replace(
		/[&<>"']/g,
		(c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
	);
const overview = [
	`${count(summary.workflows, 'workflow')} (${summary.publishedWorkflows} published, ${summary.workflowsInPersonalSpaces} in personal spaces)`,
	count(summary.apiKeys, 'API key'),
	`${count(summary.users, 'user')} and ${count(summary.pendingInvitations, 'open invitation')}`,
];

let text = `${subject}\n\n${overview.join('\n')}\n`;
let html = `<h1>${escape(subject)}</h1><p>${overview.map(escape).join('<br>')}</p>`;
for (const section of sections) {
	const shown = section.entries.slice(0, MAX_ENTRIES);
	const more = section.entries.length - shown.length;
	text += `\n${section.title}: ${section.entries.length}\n`;
	text += shown.map((entry) => `- ${entry.text}${entry.link ? ` ${entry.link}` : ''}\n`).join('');
	if (more > 0) text += `- and ${more} more\n`;
	html += `<h2>${escape(section.title)}: ${section.entries.length}</h2>`;
	if (shown.length > 0) {
		html += `<ul>${shown
			.map((entry) =>
				entry.link
					? `<li><a href="${escape(entry.link)}">${escape(entry.text)}</a></li>`
					: `<li>${escape(entry.text)}</li>`,
			)
			.join('')}${more > 0 ? `<li>and ${more} more</li>` : ''}</ul>`;
	}
}

return [{ json: { subject, findings, summary, sections, text, html } }];
